#include "runtime_short_kernel.hpp"
#include <fcntl.h>
#include <sys/stat.h>
int main(int argc,char**argv){if(argc!=2)return 2;std::array<int,496>core,out;core.fill(-1);out.fill(-1);std::array<int,160>bias;bias.fill(1000000);for(unsigned t=0;t<160;++t){core[archdata::NETS[t].to]=t;out[archdata::NETS[t].from]=t;}for(auto a:archdata::ARCS)if(core[a.from]>=0&&out[a.to]>=0)bias[out[a.to]]=std::min(bias[out[a.to]],int(a.delay+archdata::NETS[out[a.to]].delay));int fd=open(argv[1],O_RDONLY);struct stat st;fstat(fd,&st);auto*m=(const unsigned char*)mmap(nullptr,st.st_size,PROT_READ,MAP_PRIVATE,fd,0);uint32_t h[6];std::memcpy(h,m+72,24);size_t rows=size_t(h[0])*h[2]*h[3];auto*p=m+96+h[2]*2;std::array<uint64_t,17>counts{};int maxspan=0,minimum=INT_MAX,maximum=INT_MIN;for(size_t r=0;r<rows;++r){int lo=INT_MAX,hi=INT_MIN;for(unsigned t=0;t<160;++t){int a=int(RuntimeShortKernel::View::raw(p+r*220,t))+int32_t(h[5])-bias[t];lo=std::min(lo,a);hi=std::max(hi,a);}minimum=std::min(minimum,lo);maximum=std::max(maximum,hi);unsigned span=hi-lo,b=1;while((1u<<b)<=span)++b;++counts[b];maxspan=std::max(maxspan,int(span));}std::cout<<"rows="<<rows<<" max_span="<<maxspan<<" global_min="<<minimum<<" global_max="<<maximum<<'\n';for(unsigned b=0;b<17;++b)if(counts[b])std::cout<<"bits="<<b<<" rows="<<counts[b]<<'\n';std::cout<<"bias=";for(auto b:bias)std::cout<<b<<',';std::cout<<'\n';}
